fn append(v: &Vec<u64>, elem: u64) -> Vec<u64> {
    // Create a new vector with enough capacity for all elements plus the appended one.
    let mut out = Vec::with_capacity(v.len() + 1);

    // Copy elements from the input vector (input is not modified).
    out.extend_from_slice(v.as_slice());

    // Append the provided element as the last element.
    out.push(elem);

    out
}